// DEC-2026-029 follow-up: the provider invitation email links to /invitation/open with the
// attempt and a random key (32 bytes, base64url, generated by vendor-invite). The key stays
// valid until the invitation expires; each use mints a fresh single-use Auth sign-in.

export type InvitationSource = "application" | "existing_provider";

export type InvitationOpenRequest = {
  attempt: string;
  source: InvitationSource;
  key: string;
};

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const OPEN_KEY = /^[A-Za-z0-9_-]{43}$/;

export const INVITATION_LINK_INVALID_MESSAGE =
  "This invitation link is no longer valid. It may have expired or already been used to accept the invitation.";

/** The link's own values, or null when any is missing or malformed. */
export function parseInvitationOpenRequest(value: {
  invitation?: unknown;
  kind?: unknown;
  key?: unknown;
}): InvitationOpenRequest | null {
  const { invitation, kind, key } = value;
  if (typeof invitation !== "string" || !UUID.test(invitation)) return null;
  if (typeof key !== "string" || !OPEN_KEY.test(key)) return null;
  if (kind !== undefined && kind !== null && kind !== "existing_provider") return null;
  return {
    attempt: invitation.toLowerCase(),
    source: kind === "existing_provider" ? "existing_provider" : "application",
    key,
  };
}

/** Where the minted sign-in lands: the existing password step, then /invitation. */
export function invitationSetPasswordPath(request: InvitationOpenRequest, tokenHash: string): string {
  const params = new URLSearchParams({ invitation: request.attempt });
  if (request.source === "existing_provider") params.set("kind", "existing_provider");
  params.set("token_hash", tokenHash);
  params.set("type", "magiclink");
  return `/set-password?${params.toString()}`;
}
